SINA_SMART["genetics1-replication"] = {"lecture":"genetics1-replication","title":"DNA replication","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"genetics1-replication:e0","text":"Replication is semi-conservative (Meselson-Stahl).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e1","text":"Needs template, polymerases, dNTPs, ATP, Mg²⁺; synthesis 5′→3′.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e2","text":"ORC recognises origins; MCM helicase; once per cell cycle.","topic":"Initiation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e3","text":"Bacteria: one origin; eukaryotes: many, ~40 kb apart, bidirectional.","topic":"Initiation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e4","text":"Helicase unwinds (ATP); RPA protects ssDNA; topoisomerase I (no ATP) and II (ATP) relieve supercoiling.","topic":"Initiation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e5","text":"Pol α primes; Pol ε leading; Pol δ lagging; Pol β repair; Pol γ mitochondria.","topic":"Eukaryotic DNA polymerases","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e6","text":"PCNA sliding clamp increases processivity.","topic":"Eukaryotic DNA polymerases","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e7","text":"Leading: continuous, one primer. Lagging: Okazaki fragments, many primers.","topic":"Elongation and telomeres","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e8","text":"RNase H + FEN1 remove primers; ligase I seals.","topic":"Elongation and telomeres","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e9","text":"Telomerase adds TTAGGG to solve the end-replication problem.","topic":"Elongation and telomeres","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-replication:e10","text":"E. coli: Pol III, Pol I, DnaB, SSB, DnaG, β-clamp.","topic":"Termination; prokaryotes vs eukaryotes","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"185xx8x":"a","s3cnq1":"a","1hp4567":"a","knerbd":"a","ivw1s9":"a","1em2uiq":"a","18wq3cx":"a","12cf3wx":"a","15oqll7":"a","1bckwc1":"a","14k8akg":"a","7a6rue":"a","11kxyer":"a","1378rqf":"a","w5kr49":"a","1fmbnvl":"a","1i7tdaa":"a"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"genetics1-replication:e0":{"s":0,"u":["Replication is semi-conservative (Meselson-Stahl).","It is semi-conservative : each new molecule keeps one parental strand, as shown by the Meselson-Stahl experiment (after one cycle, density-gradient centrifugation showed all DNA was a hybrid of heavy and light nitrogen)."],"dp":[]},"genetics1-replication:e1":{"s":0,"u":["Needs template, polymerases, dNTPs, ATP, Mg²⁺; synthesis 5′→3′.","Requirements: DNA template, DNA polymerases, replication proteins, dNTPs , ATP and Mg²⁺ ."],"dp":[]},"genetics1-replication:e2":{"s":1,"u":["ORC recognises origins; MCM helicase; once per cell cycle.","Replication starts at an origin (Ori) , recognised by the origin recognition complex (ORC) ; licensing factors load the MCM helicase so that replication happens once per cell cycle .","Bacteria and viruses have one origin per chromosome; eukaryotic chromosomes have many , about 40 kb apart."],"dp":[]},"genetics1-replication:e3":{"s":1,"u":["Bacteria: one origin; eukaryotes: many, ~40 kb apart, bidirectional.","Bacteria and viruses have one origin per chromosome; eukaryotic chromosomes have many , about 40 kb apart.","Each origin opens a replication bubble with two forks moving in opposite directions (bidirectional); bubbles fuse where they meet."],"dp":[]},"genetics1-replication:e4":{"s":1,"u":["Helicase unwinds (ATP); RPA protects ssDNA; topoisomerase I (no ATP) and II (ATP) relieve supercoiling.","Helicase unwinds DNA using ATP, breaking hydrogen bonds; single-strand binding proteins (RPA) stabilise and protect single strands and recruit Pol α-primase; topoisomerases relieve supercoiling ahead of the fork: type I cuts one strand without ATP (mild supercoiling), type II (gyrase in bacteria) cuts both strands with ATP (severe supercoiling)."],"dp":[]},"genetics1-replication:e5":{"s":2,"u":["Pol α primes; Pol ε leading; Pol δ lagging; Pol β repair; Pol γ mitochondria.","Pol β : DNA repair (base excision), not replication.","Pol ε : leading strand ; proofreading; needs PCNA."],"dp":[]},"genetics1-replication:e6":{"s":2,"u":["PCNA sliding clamp increases processivity.","PCNA (proliferating cell nuclear antigen) is the ring-shaped sliding clamp , loaded by replication factor C, that keeps Pol δ/ε on DNA and raises processivity.","Pol α : with primase, starts synthesis (primers); no 3′→5′ exonuclease; low processivity."],"dp":[]},"genetics1-replication:e7":{"s":3,"u":["Leading: continuous, one primer. Lagging: Okazaki fragments, many primers.","Lagging strand : discontinuous Okazaki fragments , away from the fork; many primers; extended by Pol δ ; primers removed by RNase H + FEN1 ; gaps filled by Pol δ; fragments sealed by DNA ligase I .","Leading strand : continuous, toward the fork, on the 3′→5′ parental template; one RNA-DNA primer (10-20 nt) by Pol α-primase; extended by Pol ε ."],"dp":[{"h":"Why one strand is made in pieces","t":"Polymerases only add nucleotides to a 3′-OH, so they can only build 5′→3′. At a fork, one template lets the new strand grow continuously in the direction the fork moves; the other points the opposite way, so the new strand must be started again and again as the fork opens, giving Okazaki fragments that are later joined. Source: the lecture's leading vs lagging strand slides."}]},"genetics1-replication:e8":{"s":3,"u":["RNase H + FEN1 remove primers; ligase I seals.","Lagging strand : discontinuous Okazaki fragments , away from the fork; many primers; extended by Pol δ ; primers removed by RNase H + FEN1 ; gaps filled by Pol δ; fragments sealed by DNA ligase I ."],"dp":[]},"genetics1-replication:e9":{"s":3,"u":["Telomerase adds TTAGGG to solve the end-replication problem.","End-replication problem : removing the last primer at chromosome ends leaves a gap, so telomeres shorten with each division; telomerase (an RNA-dependent DNA polymerase, reverse transcriptase) extends the 3′ end with TTAGGG repeats."],"dp":[{"h":"Why telomeres shorten and why it matters","t":"At the very end of a chromosome there is no DNA beyond the last primer to fill the gap once that primer is removed, so each division trims a little telomere. Telomerase re-extends the ends in stem and germ cells; in most body cells telomeres shorten over time, a limit on cell divisions linked to ageing, while cancer cells often reactivate telomerase. Source: the lecture's telomere replication slide."}]},"genetics1-replication:e10":{"s":4,"u":["E. coli: Pol III, Pol I, DnaB, SSB, DnaG, β-clamp.","Prokaryotes (E. coli) vs eukaryotes : main polymerase Pol III vs Pol δ/ε; primer removal Pol I vs RNase H + FEN1 + Pol δ; helicase DnaB vs CMG; SSB vs RPA; primase DnaG vs primase-Pol α; clamp β-clamp vs PCNA; ligase vs ligase I; gyrase/topo II in both."],"dp":[]}},"meta":{"185xx8x":{"a":"recall","vg":"genetics1-replication:e0/recall/1"},"s3cnq1":{"a":"recall","vg":"genetics1-replication:e1/recall/1"},"1hp4567":{"a":"recall","vg":"genetics1-replication:e2/recall/1"},"knerbd":{"a":"recall","vg":"genetics1-replication:e3/recall/1"},"ivw1s9":{"a":"recall","vg":"genetics1-replication:e4/recall/1"},"1em2uiq":{"a":"recall","vg":"genetics1-replication:e4/recall/2"},"18wq3cx":{"a":"recall","vg":"genetics1-replication:e4/recall/3"},"12cf3wx":{"a":"recall","vg":"genetics1-replication:e5/recall/1"},"15oqll7":{"a":"recall","vg":"genetics1-replication:e5/recall/1"},"1bckwc1":{"a":"recall","vg":"genetics1-replication:e5/recall/2"},"14k8akg":{"a":"recall","vg":"genetics1-replication:e6/recall/1"},"7a6rue":{"a":"recall","vg":"genetics1-replication:e7/recall/1"},"11kxyer":{"a":"recall","vg":"genetics1-replication:e8/recall/1"},"1378rqf":{"a":"recall","vg":"genetics1-replication:e8/recall/2"},"w5kr49":{"a":"recall","vg":"genetics1-replication:e9/recall/1"},"1fmbnvl":{"a":"recall","vg":"genetics1-replication:e10/recall/1"},"1i7tdaa":{"a":"recall","vg":"genetics1-replication:e0/recall/2"}},"explRev":"a0b86034040c"};
